select qs.id,gs.id,t.id,$q$Polícia Civil do Ceará – Oficial Investigador de Polícia$q$,2025,$q$Oficial Investigador de Polícia$q$,$q$UECE-CEV$q$,v.n,v.subj,v.txt,v.txt,v.ans,v.pg,v.st,v.legal,v.ctx,v.note
from (values (48,$q$Noções de Direito Penal$q$,$q$No Brasil, o Princípio da Anterioridade da Lei penal, também conhecido como Princípio da Prévia Legalidade, encontra-se previsto
(A) na Lei Especial de Execução Penal.
(B) no Código Penal e na Constituição Federal.
(C) somente na Constituição Federal.
(D) somente na Lei Processual Penal brasileira.
(E) somente no Código Penal brasileiro.$q$,$q$B$q$,10,$q$under_review$q$,true,false,$q$Importada do caderno oficial (Tipo 1) e conferida com o gabarito definitivo em 27/09/2026; aguardando revisão de conteúdo.$q$),(49,$q$Noções de Direito Penal$q$,$q$A ação penal pública, no direito penal brasileiro, é aquela que depende de iniciativa do Ministério Público, ou seja, do Estado. Em uma ação penal pública, o sujeito ativo é
(A) a vítima da ação criminosa.
(B) aquele que apura o crime.
(C) aquele que comete o crime.
(D) aquele que denuncia o crime.
(E) o titular da ação penal.$q$,$q$C$q$,10,$q$under_review$q$,true,false,$q$Importada do caderno oficial (Tipo 1) e conferida com o gabarito definitivo em 27/09/2026; aguardando revisão de conteúdo.$q$),(50,$q$Noções de Direito Penal$q$,$q$Assinale a opção que corresponde a um tipo de crime praticado contra a incolumidade pública.
(A) charlatanismo
(B) feminicídio
(C) infanticídio
(D) rufianismo
(E) sequestro$q$,$q$A$q$,10,$q$under_review$q$,true,false,$q$Importada do caderno oficial (Tipo 1) e conferida com o gabarito definitivo em 27/09/2026; aguardando revisão de conteúdo.$q$),(51,$q$Noções de Direito Penal$q$,$q$Causas excludentes de culpabilidade dizem respeito a circunstâncias que afastam o juízo de reprovação da conduta injusta, mesmo que ela seja típica ou antijurídica. Sendo assim, assinale a opção que corresponde a uma causa excludente de culpabilidade.
(A) coação moral irresistível
(B) estado de necessidade
(C) estrito cumprimento de dever legal
(D) exercício regular de direito
(E) legítima defesa$q$,$q$A$q$,11,$q$under_review$q$,true,false,$q$Importada do caderno oficial (Tipo 1) e conferida com o gabarito definitivo em 27/09/2026; aguardando revisão de conteúdo.$q$),(52,$q$Noções de Direito Penal$q$,$q$Considerando o Código Penal Brasileiro, é correto afirmar que são crimes praticados contra a pessoa:
(A) apropriação indébita, violação de domicílio, invasão de dispositivo informático, roubo, furto, receptação e extorsão.
(B) intimidação sistemática, apropriação indébita, estelionato e sonegação ou destruição de correspondência.
(C) intimidação sistemática, estelionato, extorsão, violência doméstica e sonegação ou destruição de correspondência.
(D) intimidação sistemática, violação de domicílio, invasão de dispositivo informático e sonegação ou destruição de correspondência.
(E) roubo, furto, violação de domicílio, violência doméstica, invasão de dispositivo informático e apropriação indébita.$q$,$q$D$q$,11,$q$under_review$q$,true,false,$q$Importada do caderno oficial (Tipo 1) e conferida com o gabarito definitivo em 27/09/2026; aguardando revisão de conteúdo.$q$),(53,$q$Noções de Direito Penal$q$,$q$Assinale a opção que corresponde a crimes contra a Administração Pública, que só podem ser cometidos por funcionário público.
(A) corrupção ativa, descaminho, excesso de exação e condescendência criminosa
(B) peculato, excesso de exação, concussão e condescendência criminosa
(C) favorecimento pessoal, concussão, corrupção ativa e tráfico de influência
(D) peculato, concussão, tráfico de influência e favorecimento pessoal
(E) peculato, descaminho, condescendência criminosa e corrupção ativa$q$,$q$B$q$,11,$q$under_review$q$,true,false,$q$Importada do caderno oficial (Tipo 1) e conferida com o gabarito definitivo em 27/09/2026; aguardando revisão de conteúdo.$q$),(54,$q$Noções de Direito Penal$q$,$q$De acordo com o Código Penal Brasileiro, assinale a opção que apresenta somente crimes praticados contra a paz pública.
(A) associação criminosa, falsidade ideológica, moeda falsa e uso de documento falso
(B) falsificação de documento público, falsidade ideológica e apologia de crime ou criminoso
(C) falsificação de documento público, incitação ao crime e uso de documento falso
(D) uso de documento falso, incitação ao crime, moeda falsa, e apologia de crime ou criminoso
(E) associação criminosa, incitação ao crime e apologia de crime ou criminoso$q$,$q$E$q$,11,$q$under_review$q$,true,false,$q$Importada do caderno oficial (Tipo 1) e conferida com o gabarito definitivo em 27/09/2026; aguardando revisão de conteúdo.$q$),(55,$q$Noções de Direito Penal$q$,$q$Um estudante de Direito afirmou que o Inquérito Policial I. é um procedimento administrativo formal; II. é um processo penal inquisitório e oficial; III. é fundamental para a decretação de medidas cautelares; IV. tem a função de colher elementos de autoria e materialidade; V. não pode ser arquivado por determinação da autoridade policial. Estão corretas as complementações contidas em
(A) I, III e V apenas.
(B) IV apenas.
(C) I, II, III e IV apenas.
(D) I, II, III, IV e V.
(E) II e V apenas.$q$,$q$X$q$,11,$q$annulled$q$,true,false,$q$Importada do caderno oficial (Tipo 1) e conferida com o gabarito definitivo em 27/09/2026; aguardando revisão de conteúdo.$q$)) v(n,subj,txt,ans,pg,st,legal,ctx,note)
